      "fullText" : "这个说的是别把东西糊在一起，要 chunk it。\n\n多数的时候，不是做不好，而是没方向。是的，看不清方向，就想着如何狂奔。有的走路都没走好，就研究怎么飞。\n\n细节没那么重要，人之所以喜欢谈细节，仅仅是因为它容易（反着看就是人脑很蠢，喜欢假装努力）。 https://t.co/fUQOTI6sxf",
