      "fullText" : "作为一个后端工程想开始前端技术，说实话我这几天看了一下前端技术真的是让我开眼了，让我眼花缭乱。\n有没有前端大佬能个我介绍一下现在比较易用的工作前端技术的学习路径基础一点的，我只有javascript经验，我在先给大家鞠躬了。",
